w:r.w:t:
%Выводим формулы магнитного маяка
m0 = 4e-7*pi;%Магнитная постоянная
mynorm = @(r) (sqrt(sum(r.^2)));

l = sym('l', {'real'});
t = sym('t', {'real'});
rm = l.*[1, 0, 0];%Параметрически заданная кривая, описывающая соленоид
x = sym('x',{'real'});
y = sym('y',{'real'});
z = sym('z',{'real'});
r = [x, y, z];
m = 1; %Модуль магнитного момента соленоида.
%L = 0.25; %Длинна соленоида.
L = sym('L', {'real'})
ro = sym('rho', {'real'});
Bmr = sym('Bmr', {'real'});
rom = [1, 0, 0]; % Вектор магнитной плотности. Постоянен на всей длинне сленоида. 
B1 = Bmr * (3*(r-rm)*dot(rom, (r-rm))/mynorm(r-rm)^5 - rom/mynorm(r-rm)^3)%Bmr = (ro*m0/(4*pi))
%B_dip = Bmr * L * (3*r*dot(rom, r)/mynorm(r)^5 - rom/mynorm(r)^3)


bb(1) = int( B1(1)*norm(diff(rm)), l);
bb(2) = int( B1(2)*norm(diff(rm)), l);
bb(3) = int( B1(3)*norm(diff(rm)), l);

rm = l.*[0, 1, 0];%Параметрически заданная кривая, описывающая соленоид
rom = [0, 1, 0]; % Вектор магнитной плотности. Постоянен на всей длинне сленоида
B2 = Bmr * (3*(r-rm)*dot(rom, (r-rm))/mynorm(r-rm)^5 - rom/mynorm(r-rm)^3);%Bmr = (ro*m0/(4*pi))

bb2(1) = int( B2(1)*norm(diff(rm)), l);
bb2(2) = int( B2(2)*norm(diff(rm)), l);
bb2(3) = int( B2(3)*norm(diff(rm)), l);

Bx = subs(bb(1), l, L/2) - subs(bb(1), l, -L/2) + subs(bb2(1), l, L/2) - subs(bb2(1), l, -L/2);
By = subs(bb(2), l, L/2) - subs(bb(2), l, -L/2) + subs(bb2(2), l, L/2) - subs(bb2(2), l, -L/2);
Bz = subs(bb(3), l, L/2) - subs(bb(3), l, -L/2) + subs(bb2(3), l, L/2) - subs(bb2(3), l, -L/2);

Bd = [subs(bb(1), l, L/2) - subs(bb(1), l, -L/2), subs(bb2(1), l, L/2) - subs(bb2(1), l, -L/2);...
     subs(bb(2), l, L/2) - subs(bb(2), l, -L/2), subs(bb2(2), l, L/2) - subs(bb2(2), l, -L/2);...
     subs(bb(3), l, L/2) - subs(bb(3), l, -L/2), subs(bb2(3), l, L/2) - subs(bb2(3), l, -L/2)];
BB(:,1) = Bd(:,2);
BB(:,2) = Bd(:,1);
Bd = BB

%Получение функций
fn_Bx = matlabFunction(Bx);
fn_By = matlabFunction(By);
fn_Bz = matlabFunction(Bz);

dip = MagneticMoment(0, 0, 0, 1, 1, 0)
N = 100;
x = linspace(-4, 4, N);
y = linspace(-4, 4, N);
z = linspace(-4, 4, N);
bx = zeros(N, N, N);
by = zeros(N, N, N);
bz = zeros(N, N, N);
bx3 = zeros(N, N, N);
by3 = zeros(N, N, N);
bz3 = zeros(N, N, N);
for i = 1:numel(x)
    for j = 1:numel(y)
        for k = 1:numel(z)
            [bx(i, j, k), by(i, j, k), bz(i, j, k)] = dip.Field(x(i), y(j), z(k));

            bx3(i, j, k) = fn_Bx(m/L, x(i), y(j), z(k));
            by3(i, j, k) = fn_By(m/L, x(i), y(j), z(k));
            bz3(i, j, k) = fn_Bz(m/L, x(i), y(j), z(k));
        end
    end
end

figure;
[X, Y] = meshgrid(x, y);
%quiver(X(1:n:end), Y(1:n:end), bx(1:n:end)./nrm(1:n:end), -by(1:n:end)./nrm(1:n:end))

%strmsl1 = streamslice(X, Y, -bx(:, :, 50), by(:, :, 50));
hold on

strmsl3 = streamslice(X, Y, -bx3(:, :, 50), by3(:, :, 50));
for i = 1:numel(strmsl3)
    strmsl3(i).Color = [1,0,0];
end
